package fileheader

import (
	"go/parser"
	"go/token"
	"strings"
	"testing"
)

// TestGo_ParsesAsAFileCommentAndNotAsThePackageDoc verifies that a Go file
// opened with [Go] keeps the header out of the package's doc comment, both
// above the package clause and above a "Code generated" line, and that the
// header is the file's first comment group, carrying both statements.
func TestGo_ParsesAsAFileCommentAndNotAsThePackageDoc(t *testing.T) {
	tests := []struct {
		name    string
		body    string
		wantDoc string
	}{
		{name: "package clause", body: "package demo\n", wantDoc: ""},
		{name: "package doc comment", body: "// Package demo is a demo.\npackage demo\n", wantDoc: "Package demo is a demo.\n"},
		{name: "generated marker", body: "// Code generated by a test; DO NOT EDIT.\n\npackage demo\n", wantDoc: ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			file, err := parser.ParseFile(token.NewFileSet(), "demo.go", Go+tt.body, parser.ParseComments)
			if err != nil {
				t.Fatalf("ParseFile() error = %v", err)
			}
			if got := file.Doc.Text(); got != tt.wantDoc {
				t.Errorf("package doc = %q, want %q", got, tt.wantDoc)
			}
			if got, want := file.Comments[0].Text(), CopyrightStatement+"\n"+LicenseStatement+"\n"; got != want {
				t.Errorf("first comment group = %q, want %q", got, want)
			}
		})
	}
}

// TestGo_EndsWithTheBlankLine verifies the header ends with the one blank line
// that separates it from what follows, and with no more.
func TestGo_EndsWithTheBlankLine(t *testing.T) {
	if !strings.HasSuffix(Go, "\n\n") || strings.HasSuffix(Go, "\n\n\n") {
		t.Errorf("Go = %q, want it to end with exactly one blank line", Go)
	}
}
